/// @file design_resolver.h
/// @brief Spec-driven filter design derivation
///
/// Declares QualitySpec (a quality target expressed as stopband attenuation
/// and passband width), DesignConstraints (memory budget and mode flags),
/// and resolve_design(), which derives the Kaiser beta, filter length,
/// cutoff, and polyphase count for a concrete rate pair from those targets
/// using the closed-form Kaiser window design formulas. The result carries a
/// ready-to-use FilterDesign plus a report of what was actually achieved.
///
/// See docs/configuration_redesign.md for the design rationale.

#ifndef DESIGN_RESOLVER_H
#define DESIGN_RESOLVER_H

#include "resampler/filter_design.h"
#include "resampler/resampler_config.h"

#include <cstddef>
#include <cstdint>

namespace micro_resampler {

/// @brief Quality target for spec-driven filter derivation
///
/// Unlike the raw FilterDesign knobs (taps, beta, cutoff percentages), these
/// two numbers describe what the listener gets, independent of the rate
/// pair. resolve_design() turns them into concrete filter parameters once
/// the rates are known.
struct QualitySpec {
    /// Minimum stopband attenuation in dB (alias/image rejection)
    double stopband_db = 80.0;

    /// Passband edge as a fraction (0-1) of the lower of the two Nyquist
    /// frequencies. The transition band spans from here to that Nyquist
    double passband_fraction = 0.90;
};

/// @brief Map a ResamplerQuality preset to its quality specification
/// @note Preset values are provisional pending sweep validation (see
/// docs/configuration_redesign.md)
/// @param quality Quality preset to translate
/// @return the stopband/passband specification for the preset
QualitySpec quality_spec_from_preset(ResamplerQuality quality);

/// @brief How the resolved design maps output samples onto polyphase branches
enum class PhaseMode : uint8_t {
    EXACT,         ///< One phase per GCD-simplified output step; no blending (1x dot product)
    INTERPOLATED,  ///< Linear blend between adjacent phases (2x dot products)
};

/// @brief Optional constraints on the resolved design
struct DesignConstraints {
    /// Filter bank memory budget in bytes (0 = unlimited). When the
    /// CPU-first exact-phase bank exceeds this, the resolver falls back to
    /// interpolated phases, then to a shorter filter with a reduced
    /// passband. Stopband attenuation is never sacrificed
    size_t memory_budget_bytes = 0;

    /// Bytes per filter coefficient: sizeof(CoeffFormat::coefficient_t)
    /// (2 for Q15Format, 4 for Q31/Float32, 8 for Float64)
    size_t bytes_per_coefficient = 2;

    /// True when designing for ASRC. A drifting ratio never lands on a
    /// phase grid, so exact phase mode is unavailable and the resolver
    /// always selects INTERPOLATED
    bool asrc = false;

    /// True when coefficients will be generated by a table-based Kaiser
    /// strategy (TABLE_FLOAT / TABLE_DOUBLE, the ESP32 default), which only
    /// supports beta = 6, 8, 10, or 12. The resolver then snaps beta up to
    /// the smallest grid value whose window meets the stopband target and
    /// sizes the filter for that window. Targets above the grid ceiling
    /// (~117.6 dB at beta 12) are clamped and reported via
    /// achieved_stopband_db. Populate with precision_uses_beta_table()
    bool table_beta_grid = false;
};

/// @brief A resolved filter design plus a report of what was achieved
///
/// The design member can be passed directly to the MicroResampler
/// FilterDesign constructors. The remaining fields expose the trade-offs
/// the resolver made so callers can log or assert on them.
struct ResolvedDesign {
    /// Ready-to-use filter design (length, beta, cutoffs, phase count)
    FilterDesign design = FilterDesign::from_quality(ResamplerQuality::MEDIUM);

    /// Whether output samples use one exact phase or blend two
    PhaseMode phase_mode = PhaseMode::EXACT;

    /// Polyphase branch count the resampler will use
    int phases = 1;

    /// FIR taps per polyphase branch (multiple of 8)
    int filter_length = 0;

    /// Kaiser window beta derived from the stopband target; snapped to the
    /// table grid when DesignConstraints::table_beta_grid is set
    double kaiser_beta = 0.0;

    /// Stopband attenuation actually delivered in dB: what the Kaiser
    /// window is designed for (the requested target, or the snapped-beta
    /// window when the table grid is in effect), floored by the
    /// phase-interpolation image suppression when interpolating
    double achieved_stopband_db = 0.0;

    /// Passband edge actually delivered in Hz. Matches the request unless a
    /// memory budget or MAX_FILTER_LENGTH forced a shorter filter, in which
    /// case the transition band widened downward
    double achieved_passband_hz = 0.0;

    /// Passband edge originally requested in Hz
    double requested_passband_hz = 0.0;

    /// Filter bank size: phases * filter_length * bytes_per_coefficient
    size_t filter_bank_bytes = 0;

    /// Dot products per output sample (1 exact, 2 interpolated)
    int dotprods_per_output = 1;

    /// False if the constraints cannot hold even a minimal filter, or the
    /// inputs were invalid. The other fields are best-effort in that case
    bool feasible = false;
};

/// @brief Derive concrete filter parameters from a quality specification
///
/// Applies the Kaiser window design formulas: beta from the stopband
/// target, filter length from the transition width (passband edge to the
/// lower Nyquist, normalized to the input rate), and the sinc cutoff at the
/// center of the transition band. Phase selection is CPU-first: exact
/// phases (GCD-simplified output rate) whenever they fit the constraints,
/// otherwise linear interpolation with enough phases to keep interpolation
/// images below the stopband target.
///
/// @param spec Quality target (stopband dB, passband fraction)
/// @param input_rate Input sample rate in Hz
/// @param output_rate Output sample rate in Hz (for ASRC, the nominal rate)
/// @param constraints Optional memory budget and mode flags
/// @return the resolved design and report; check ResolvedDesign::feasible
ResolvedDesign resolve_design(const QualitySpec& spec, uint32_t input_rate, uint32_t output_rate,
                              const DesignConstraints& constraints = DesignConstraints());

/// @brief Whether a precision strategy draws Kaiser windows from the fixed
/// beta table
///
/// TABLE_FLOAT and TABLE_DOUBLE always do; DEFAULT resolves to whatever
/// strategy the platform defaults to (table-based on ESP32, computed on
/// desktop). Use the result to populate DesignConstraints::table_beta_grid
/// @param precision Coefficient-generation precision strategy
/// @return true when generation is restricted to the beta = 6/8/10/12 grid
bool precision_uses_beta_table(PrecisionStrategyType precision);

}  // namespace micro_resampler

#endif  // DESIGN_RESOLVER_H
